posts.body:
Try this, not tested. Paste the below into a text editor, save as a *.js file, include as a plugin beneath the Aftermath Level Up.
Code:
var origVictoryPostLevel = BattleManager.prepareVictoryPostLevel;
BattleManager.prepareVictoryPostLevel = function()
{
    origVictoryPostLevel.call(this);

    if (this._leveledActors.length)
    {
        let actorList = this._leveledActors;
        actorList.sort((a, b) => a.name() - b.name());
        let musicName = "";
        actorList.forEach(actor => musicName += actor.name());
        Yanfly.Param.VABgmName = musicName;
    }
};
Then, in the Victory Aftermath plugin, take line 342 and cut it, pasting it after line 344 (before the closing brace).
This will look for an audio track in your BGM folder that has the names of the actors in alphabetical order. Example: HaroldLuciusTherese.ogg
